 "params":{"XL":0.15,"mp":0.01,"mq":0.05,"TPf":0.01,"TQf":0.01,"TVf":0.01,"kiv":5.86,"kpv":0.0,"Emax":1.15,"Emin":0.0},
 "defs":{
   "phi":"atan2(XL*P0, XL*Q0+V0**2)",
   "E0":"clip(sqrt((XL*Q0+V0**2)**2+(XL*P0)**2)/V0, Emin, Emax)",
   "Vcmd":"Vset + mq*(Q0 - Qm)",
   "Ei":"clip(kpv*(Vcmd - Vm) + xv, Emin, Emax)",
   "ph":"delta - theta"
 },
 "states":{
   "Pm":{"rhs":"(P - Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Q - Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V - Vm)/TVf","init":"V0"},
   "xv":{"rhs":"kiv*(Vcmd - Vm)","init":"E0"},
   "delta":{"rhs":"2*pi*60*mp*(P0 - Pm)","init":"theta0+phi"}
 },
 "outputs":{"P":"Ei*V*sin(ph)/XL","Q":"(Ei*V*cos(ph)-V**2)/XL"}
}
